const searchTransactions = `-- name: SearchTransactions :many


SELECT t.id, t.run_id, r.agent_id, t.operation, t.connection_id, t.decision, t.reason_code, t.mode, t.effect_state,
       t.target_type, t.target_id, t.created_at, t.simulated, e.kind AS environment_kind
FROM pc.transactions t
JOIN pc.runs r ON r.org_id = t.org_id AND r.id = t.run_id
JOIN pc.environments e ON e.org_id = r.org_id AND e.id = r.environment_id
WHERE t.org_id = $1
  AND ($2::boolean OR r.agent_id = ANY ($3::uuid[]))
  AND ($4::uuid IS NULL OR t.id < $4::uuid)
  AND ($5::uuid IS NULL OR t.id = $5::uuid)
  AND ($6::uuid IS NULL OR r.agent_id = $6::uuid)
  AND ($7::uuid IS NULL OR t.run_id = $7::uuid)
  AND ($8::uuid IS NULL OR t.connection_id = $8::uuid)
  AND ($9::uuid IS NULL OR t.grant_id = $9::uuid)
  AND ($10::uuid IS NULL OR r.principal_user_id = $10::uuid)
  AND ($11::uuid IS NULL OR r.principal_sa_id = $11::uuid)
  AND ($12::text = '' OR t.operation = $12::text)
  AND ($13::text = '' OR starts_with(t.operation, $13::text))
  AND ($14::text = '' OR t.target_type = $14::text)
  AND (cardinality($15::text[]) = 0 OR t.decision = ANY ($15::text[]))
  AND (cardinality($16::text[]) = 0 OR t.mode = ANY ($16::text[]))
  AND (cardinality($17::text[]) = 0 OR e.kind = ANY ($17::text[]))
  AND ($18::timestamptz IS NULL OR t.created_at >= $18::timestamptz)
  AND ($19::timestamptz IS NULL OR t.created_at < $19::timestamptz)
ORDER BY t.id DESC
LIMIT $20
`

